;------------------------------------------------------------------------------; Auteur..........: Daniel Lafrance, Trois-Rivières, Québec, Canada; Nom du fichier..: m-c64-utils.asm; Type fichier....: Macros; Scripteur.......: Daniel Lafrance, Québec, canada.; version.........: 0.1.0; Revision........: 20151126;                   20261101  Vérification et francisation des commentaires.;------------------------------------------------------------------------------;------------------------------------------------------------------------------; Place dans ZP1 une adresse reçu en paramètre.                            OK;------------------------------------------------------------------------------setzpage1      .macro addr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda  #<\addr         ; Charge le LSB du paramètre               sta  zpage1          ; ... le place dans $00fb.               lda  #>\addr+1       ; Charge le MSB du paramètre               sta  zpage1+1        ; ... le place dans $00fc.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Place dans ZP2 une adresse reçu en paramètre.                            OK;------------------------------------------------------------------------------setzpage2      .macro addr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda  #<\addr         ; Charge le LSB du paramètre               sta  zpage2          ; ... le place dans $00fb.               lda  #>\addr+1       ; Charge le MSB du paramètre               sta  zpage2+1        ; ... le place dans $00fc.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp1data      .macro ptr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   \ptr           ; Charge le LSB du ptr               sta   zpage1         ; ... copie dans LSB de zpage1.               lda   \ptr+1         ; Charge le MSB du ptr               sta   zpage1+1       ; ... copie dans MSB de zpage1.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------stzp1data      .macro ptr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   zpage1         ; ... copie dans LSB de zpage1.               sta   \ptr           ; Charge le LSB du ptr               lda   zpage1+1       ; ... copie dans MSB de zpage1.               sta   \ptr+1         ; Charge le MSB du ptr               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp2data      .macro ptr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   \ptr           ; Charge le LSB du ptr               sta   zpage2         ; ... copie dans LSB de zpage2.               lda   \ptr+1         ; Charge le MSB du ptr               sta   zpage2+1       ; ... copie dans MSB de zpage2.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp1ptr       .macro immval               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #<\immval      ;Charge le LSB du ptr et               sta   zpage1         ; ... copie dans LSB de zpage1.               lda   #>\immval      ;Charge le MSB du ptr et               sta   zpage1+1       ; ... copie dans MSB de zpage1.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Sauvegarde dans zpage1 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------stzp1ptr       .macro immval               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   zpage1         ; ... copie dans LSB de zpage1.               sta   #<\immval      ;Charge le LSB du ptr et               lda   zpage1+1       ; ... copie dans MSB de zpage1.               sta   #>\immval      ;Charge le MSB du ptr et               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Charge dans zpage2 un nombre 16 bits donnée en paramètre.                OK;------------------------------------------------------------------------------ldzp2ptr       .macro immval               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #<\immval      ;Charge le LSB du ptr et               sta   zpage2         ; ... copie dans LSB de zpage2.               lda   #>\immval      ;Charge le MSB du ptr et               sta   zpage2+1       ; ... copie dans MSB de zpage2.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Place une valeur 16 bits en mémoire à l'adresse donnée en paramètre.     OK;------------------------------------------------------------------------------wordtomem      .macro mot,ptr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #<\mot         ; Charge le LSB de la valeur en param.               sta   \ptr           ; ... et le place en mémoire.                                         lda   #>\mot         ; Charge le MSB de la valeur en param.               sta   \ptr+1         ; ... et le place en mémoire.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm ;------------------------------------------------------------------------------; Charge dans $YYXX le contenu de ladresse 16 bits donnée en paramètre.    OK;------------------------------------------------------------------------------ldyxdata       .macro ptr               php                  ; Sauvegarde les drapeauc du CPU.               ldx   \ptr           ; Charge le LSB du pointeur.               ldy   \ptr+1         ; Charge le MSB du pointeur.               plp                  ; Récupère les drapeaux du CPU.               .endm;------------------------------------------------------------------------------; Charge dans $xxyy le contenu de ladresse 16 bits donnée en paramètre.    OK;------------------------------------------------------------------------------ldxydata       .macro ptr               php                  ; Sauvegarde les drapeauc du CPU.               ldy   \ptr           ; Charge le LSB du pointeur.               ldx   \ptr+1         ; Charge le MSB du pointeur.               plp                  ; Récupère les drapeaux du CPU.               .endm;------------------------------------------------------------------------------; Sauvegarde le contenu 16 bits $YYXX l'adresse donnée en paramètre.       OK;------------------------------------------------------------------------------styxdata       .macro ptr               stx   \ptr           ; Écrit le LSB du pointeur.               sty   \ptr+1         ; Écrit le MSB du pointeur.               .endm;------------------------------------------------------------------------------; Sauvegarde le contenu 16 bits $XXYY l'adresse donnée en paramètre.       OK;------------------------------------------------------------------------------stxydata       .macro ptr               sty   \ptr           ; Écrit le LSB du pointeur.                stx   \ptr+1         ; Écrit le MSB du pointeur.               .endm;------------------------------------------------------------------------------; Charge dans $YYXX le nombre 16 bits donnée en paramètre.                 OK;------------------------------------------------------------------------------ldyxptr        .macro immval               php                  ; Sauvegarde les drapeauc du CPU.               ldx   #<\immval      ; Charge le LSB de la valeur dans X.               ldy   #>\immval      ; Charge le MSB de la valeur dans Y.               plp                  ; Récupère les drapeaux du CPU.               .endm;------------------------------------------------------------------------------; Charge dans $XXYY le nombre 16 bits donnée en paramètre.                 OK;------------------------------------------------------------------------------ldxyptr        .macro immval               php                  ; Sauvegarde les drapeauc du CPU.               ldy   #<\immval      ; Charge le LSB de la valeur dans Y.               ldx   #>\immval      ; Charge le MSB de la valeur dans X.               plp                  ; Récupère les drapeaux du CPU.               .endm;------------------------------------------------------------------------------; Charge dans $AAXX le contenu de ladresse 16 bits donnée en paramètre.    OK;------------------------------------------------------------------------------ldaxdata       .macro axadd               php                  ; Sauvegarde les drapeauc du CPU.               lda   \axadd+1       ; Charge le MSB de l'adresse dans A.               ldx   \axadd         ; Charge le LSB de l'adresse dans X.               plp                  ; Récupère les drapeaux du CPU.               .endm;------------------------------------------------------------------------------; Charge dans $AAXX un nombre 16 bits donnée en paramètre.                 OK;------------------------------------------------------------------------------ldaxptr        .macro aximm               php                  ; Sauvegarde les drapeauc du CPU.               lda   #>\aximm       ; Charge le MSB de l'adresse dans A.               ldx   #<\aximm       ; Charge le LSB de l'adresse dans X.               plp                  ; Récupère les drapeaux du CPU.               .endm;------------------------------------------------------------------------------; Affichage d'un caractere par kernal.                                     OK;------------------------------------------------------------------------------outcar         .macro carno               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #\carno        ; Charge le code dans Acc pour               jsr   chrout         ; ... l'afficher avec $ffd2.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm        ;------------------------------------------------------------------------------; Affiche une chaine de caracteres parle kernal.                           OK;------------------------------------------------------------------------------outstr         .macro string               jsr   push           ; Sauvegarde les registres.               ldy   #>\string+1    ; Le MSB de l'adresse dans Y.               ldx   #<\string      ; Le LSB de l'adresse dans X.               jsr   putsyx         ; Affiche le texte.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine de caracteres par le kernal a la position (x,y) placée ; ... au début de la chaine.                                               OK;------------------------------------------------------------------------------outstrxy       .macro string               jsr   push           ; Sauvegarde les registres.               ldx   \string        ; Charge la colonne.               ldy   \string+1      ; Charge la ligne               jsr   gotoxy         ; Positionne le curseur.               ldx   #<\string+2    ; Charge le LSB de l'adresse du texte.               ldy   #>\string+2    ; Charge le MSB de l'adresse du texte.               jsr   putsyx         ; Affiche le texte pointé par $YYXX.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Deplace le curseur a la position (x,y).                                  OK;------------------------------------------------------------------------------locate         .macro x,y               jsr   push           ; Sauvegarde les registres.               ldx #\x              ; Charge la colonne.               ldy #\y              ; Charge la ligne.               jsr gotoxy           ; Positionne le curseur.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine dont l'adresse est passé en paramètre.                OK;------------------------------------------------------------------------------print          .macro sptr               jsr   push           ; Sauvegarde les registres.               ldx   #<\sptr        ; Charge le LSB de la chaine dans X.               ldy   #>\sptr        ; Charge le MSB de la chaine dans Y.               jsr   putsyx         ; Affiche le texte.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX suivie par une crlf.                OK;------------------------------------------------------------------------------println        .macro sptr               print \sptr          ; Affiche la chaine.               lda  #$0d            ; Charge un cr-lf               jsr  chrout          ; ... et l'affiche.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y.                  OK;------------------------------------------------------------------------------print_xy       .macro x,y,sptr               #locate \x,\y        ; Positionne le curseur au (x,y).               #print \sptr         ; Affiche la chaine.               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y dans ka couleur C.; Le code de couleur vidéo est nécessaire.; La couleur actuelle est sauvegardée.                                     OK;------------------------------------------------------------------------------print_cxy      .macro c,x,y,sptr               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   bascol         ; Charge la couleur Basic               pha                  ; ... et la Sauvegarde.               lda   #\c            ; Récupère la couleur du texte               sta   bascol         ; ... et en informe Basic.               #print_xy \x,\y,\sptr; Affiche le texte à la position donnée.               pla                  ; Récupère la couleur initiale de Basic               sta   bascol         ; ... et la replace                pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y.; La position X,Y constitue les deux premier de la chaine.                 OK;------------------------------------------------------------------------------printxy        .macro sptr               jsr   push           ; Sauvegarde les registres.               ldx   #<\sptr        ; Récupère le LSB de la chaine.               ldy   #>\sptr        ; Récupère le LSB de la chaine.               jsr   putsxy         ; Appel la fonction d'impression.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX à la position X,Y dans la couleur C.; La couleur et position X,Y constitue les trois premier de la chaine.     OK;------------------------------------------------------------------------------printcxy       .macro sptr               jsr   push           ; Sauvegarde les registres.               ldx   #<\sptr        ; Récupère le LSB de la chaine.               ldy   #>\sptr        ; Récupère le LSB de la chaine.               jsr   putscxy        ; Appel la fonction d'impression.               jsr   pop            ; Récupère les registres.               .endm;------------------------------------------------------------------------------; Affiche un texte précédé d'un préfixe.                                   OK;------------------------------------------------------------------------------printfmt       .macro prfx, sptr               #outcar  \prfx       ; Affiche le préfixe.               #print   \sptr       ; Affiche la chaine.               .endm;------------------------------------------------------------------------------; Affiche un texte précédé d'un préfixe à la position X,Y.                 OK;------------------------------------------------------------------------------printxyfmt     .macro x,y,prfx,sptr               #locate \x,\y        ; Positionne le curseur au (x,y).               #printfmt \prfx,\sptr; Affiche la chaine.               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire issue d'une case memoire (indirect).   OK;------------------------------------------------------------------------------printptr16bin  .macro adresse               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #>\adresse+1   ; Charge le MSB du contenu de l'adresse,                jsr   atobin         ; ... le converti en binaire et               #printfmt "%",a2binstr;... l'affiche avec un prefixe.               lda   #<\adresse     ; Charge le lSB du contenu de l'adresse,                jsr   atobin         ; ... le converti en binaire et               #print a2binstr      ; ... l'affiche.               pla               plp               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire issue d'une case memoire (indirect).   OK;------------------------------------------------------------------------------printwordbin   .macro adresse               jsr   pushall        ; Sauvegarde les registres et des zpage1-2.               lda  #<\adresse               sta  $fb               lda  #>\adresse               sta  $fb+1               ldy  #$01                lda  ($fb),y               jsr  atobin               #printfmt "%", a2binstr               dey               lda  ($fb),y               jsr  atobin               #print a2binstr               jsr   popall         ; Récupère les registres et des zpage1-2.               .endm;------------------------------------------------------------------------------; Place sur la pile tous les registres.                                    OK;------------------------------------------------------------------------------mpushr         .macro               php                  ; Sauvegarde les drapeauc du CPU.               pha               txa               pha               tya               pha               .endm;------------------------------------------------------------------------------; Recupere les registres de la pile.                                       OK;------------------------------------------------------------------------------mpopr          .macro               pla               tay               pla               tax               pla               plp                  ; Récupère les drapeaux du CPU.               .endm        ;------------------------------------------------------------------------------; Initialise les donneed de la fonction loop.                              OK;------------------------------------------------------------------------------setloop        .macro lcount               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda  #<\lcount       ; Charge le LSB du nombre 16 bits                sta  loopcount       ; ... et le place en mémoire.               lda  #>\lcount       ; Charge le MSB du nombre 16 bits                sta  loopcount+1     ; ... et le place en mémoire.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Permet les changement de police avec [C=]+[SHIFT].                       OK;------------------------------------------------------------------------------enable         .macro               #outcar  9           ; Changement de jeu de caractères permi.               .endm;------------------------------------------------------------------------------; Inhibe les changement de police avec [C=]+[SHIFT].                       OK;------------------------------------------------------------------------------disable        .macro               #outcar  8           ; Changement de jeu de caractères inhibé.               .endm;------------------------------------------------------------------------------; Selectionne le jeu de caracteres minuscule.                              OK;------------------------------------------------------------------------------tolower        .macro               #outcar  14          ; Jeu de caractères Majuscule/minuscule.               .endm;------------------------------------------------------------------------------; Selectionne le jeu de caracteres majuscule.                              OK;------------------------------------------------------------------------------toupper        .macro               #outcar  b_uppercase ; Jeu de caractères Majuscule/graphique.               .endm;------------------------------------------------------------------------------; Change la couleur de la bordure.                                         OK;------------------------------------------------------------------------------changebord     .macro c               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #\c            ; Charge la couleur et la place dans               sta   $d020          ; ... le registre 53280 du VICII.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Change la couleur de l'arriere plan de l'ecran.                          OK;------------------------------------------------------------------------------changeback     .macro c               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda   #\c            ; Charge la couleur et la place dans               sta   $d021          ; ... le registre 53281 du VICII.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------; Sélectionne mes couleurs préférées.                                      OK;------------------------------------------------------------------------------mescol         .macro               #changebord cvert               #changeback cbleu               #color cblanc               .endm;------------------------------------------------------------------------------; Couleurs Commodore 64 + texte blanc.                                     OK;------------------------------------------------------------------------------c64col         .macro               #changebord cbleupale               #changeback cbleu               #color cblanc               .endm;------------------------------------------------------------------------------; Sélectionne les couleurs naturelle du commodore Vic 20.                  OK;------------------------------------------------------------------------------v20col         .macro               #changebord ccyan               #changeback cblanc               #color cbleu               .endm;------------------------------------------------------------------------------; Sélectionne un jeu de couleurs grises.                                   OK;------------------------------------------------------------------------------griscol        .macro               #changebord cgrismoyen               #changeback cgrisfonce               #color cgrispale               .endm;------------------------------------------------------------------------------; Sélectionne la couleur du texte.                                         OK;------------------------------------------------------------------------------color          .macro    c               php                  ; Sauvegarde minimaliste                pha                  ; ... des registres.               lda  #\c             ; Charge la couleur et la place dans               sta  bascol          ; ... la variable de la couleur Basic.               pla                  ; Récupération minimaliste               plp                  ; ... des registres.               .endm;------------------------------------------------------------------------------